
# Βρες το μεγαλύτερο γινόμενο 13 διαδοχικών ψηφίων στον τεράστιο αριθμό που δίνεται.

# Ο μεγάλος αριθμός αποθηκευμένος ως string
s = ''

# Αρχικοποίηση μεταβλητών για τα γινόμενα και τον δείκτη θέσης
suma = 1
n = 0
new_suma = 1

# Επανάληψη μέχρι ο δείκτης plus 13 να φτάσει το μήκος του string (1001 χαρακτήρες)
while n + 13 < 1001:
    # Υπολογισμός του γινομένου των 13 συνεχόμενων χαρακτήρων από τη θέση n
    for x in s[n : n + 13]:
        suma = suma * int(x)
        
    # Έλεγχος αν το τρέχον γινόμενο είναι μεγαλύτερο ή ίσο από το μέγιστο που έχουμε βρει
    if new_suma <= suma:
        new_suma = suma
        suma = 1
    else:
        new_suma = new_suma
        suma = 1
        
    # Μετάβαση στην επόμενη θέση
    n = n + 1

# Εκτύπωση του μέγιστου γινομένου (new_suma) και του τελευταιου προσωρινού (suma)
print(new_suma, suma)
  


  
    

       
    
    
